   "id": "z695c9766",
   "sez": "mondo",
   "titolo": "Sudan, attacchi con drone alle centrali elettriche lasciano le città al buio",
   "orig": "Drone attacks on power stations plunge Sudan’s cities into darkness",
   "lead": "Le centrali elettriche sudanesi sono state colpite da una serie di attacchi con drone, che hanno provocato blackout in diverse città del paese. Gli attacchi si inseriscono nel conflitto in corso in Sudan, che da mesi provoca gravi conseguenze sulle infrastrutture civili e sulla vita quotidiana della popolazione. Lo riferisce Al Jazeera.",
   "more": [
    "Il Sudan è dilaniato da una guerra civile scoppiata nell'aprile 2023 tra l'esercito regolare e le Forze di supporto rapido (RSF), con pesanti ripercussioni su infrastrutture, approvvigionamento energetico e servizi essenziali per milioni di civili."
   ],
