   "id": "z5e448a8f",
   "sez": "prima",
   "titolo": "L'Iran colpisce una base in Bahrein, Teheran ribadisce che la via diplomatica resta aperta",
   "orig": "Iran strikes Bahrain base, repeats path to U.S. deal remains open",
   "lead": "L'Iran ha attaccato con droni una base militare statunitense in Bahrein, secondo quanto riportato dal Japan Times, nel primo episodio del genere dall'inizio di settembre, quando droni iraniani avevano già preso di mira una base Usa negli Emirati. Le Guardie Rivoluzionarie iraniane hanno dichiarato che l'azione è una risposta ad \"azioni ostili americane\", secondo l'agenzia Fars. Il Bahrein ha intercettato gli attacchi, mentre contemporaneamente l'Arabia Saudita ha intercettato missili diretti su Riad e droni nella provincia orientale; le forze yemenite governative si sono ritirate da un'area vicina allo stretto di Bab el-Mandeb, lasciando il controllo agli Houthi. Teheran ribadisce che la porta a un accordo con Washington resta aperta.",
   "more": [
    "Dal 2019 la regione del Golfo è teatro di scontri indiretti tra Iran e Stati Uniti, con attacchi di milizie alleate iraniane, come gli Houthi in Yemen, contro basi americane e alleati regionali come Arabia Saudita e Bahrein. Le tensioni si inseriscono nel più ampio confronto geopolitico sul programma nucleare iraniano e sulla presenza militare statunitense nel Golfo Persico."
   ],
