   "id": "zbe387769",
   "sez": "prima",
   "titolo": "Corea del Sud, si costituisce il primo all'esame per commercialisti dopo la confessione sull'uso dell'IA",
   "orig": "(3rd LD) Top scorer in tax accountant exam turns himself in over AI-assisted cheating",
   "lead": "Il candidato risultato primo all'esame nazionale sudcoreano per diventare commercialista fiscale si è costituito alla polizia dopo aver ammesso di aver usato l'intelligenza artificiale per copiare, riferisce l'agenzia Yonhap. L'uomo ha spiegato di aver utilizzato una combinazione di microcamera, modello di IA generativa e smartphone per ottenere le risposte durante la prova, eludendo il controllo di due sorveglianti, secondo il Korea Herald. La polizia sudcoreana ha avviato un'indagine, come riferito da Dawn. Il caso, emerso dopo mesi di sospetti per i punteggi quasi perfetti ottenuti in due turni d'esame ad aprile e luglio, alimenta timori in vista del prossimo test nazionale di ammissione all'università.",
   "more": [
    "La diffusione di strumenti di intelligenza artificiale generativa capaci di rispondere rapidamente a domande complesse ha reso più difficile individuare episodi di imbroglio durante esami pubblici altamente competitivi, spingendo le autorità sudcoreane a rafforzare i controlli anti-frode in vista delle prossime prove nazionali."
   ],
