   "orig": "Doctor burnout putting maternity patients at risk, says regulator",
   "lead": "Secondo un rapporto del regolatore sanitario britannico, i medici in formazione che assistono ai parti sono più esposti al rischio di sovraccarico di lavoro e burnout rispetto ad altre specialità, con possibili conseguenze sulla sicurezza delle pazienti in gravidanza. Lo riferisce la BBC.",
