    "Il burnout tra il personale medico, soprattutto nei reparti di ostetricia dove i ritmi di lavoro sono intensi e imprevedibili, è da anni oggetto di attenzione nei sistemi sanitari pubblici, per il rischio che la stanchezza dei medici incida sulla qualità delle cure fornite ai pazienti."
