   "sez": "ambiente",
   "titolo": "COP31, l'Africa accusa l'Ue di tattiche dilatorie sui 120 miliardi per l'adattamento climatico",
   "orig": "CLIMATE CASH SHOWDOWN: Africa battles EU ‘delaying tactics’ at COP31 over $120bn climate adaptation lifeline",
   "lead": "Al COP31 il Gruppo africano, che include il Sudafrica, chiede che resti sul tavolo una proposta da 120 miliardi di rand per il finanziamento dell'adattamento climatico. Secondo negoziatori e organizzazioni della società civile citati da Daily Maverick, i paesi sviluppati, guidati dall'Unione Europea, utilizzerebbero tattiche dilatorie per evitare di specificare come e quando questi fondi saranno effettivamente erogati. Lo riferisce Daily Maverick.",
   "more": [
    "Le conferenze delle Nazioni Unite sul clima (COP) sono il principale forum negoziale internazionale sulla riduzione delle emissioni e sul finanziamento climatico; i paesi in via di sviluppo chiedono da anni ai paesi ricchi fondi certi per adattarsi agli effetti del cambiamento climatico, spesso lamentando ritardi nell'erogazione promessa."
   ],
