   "sez": "cultura",
   "titolo": "Una tecnologia immersiva riporta in vita i dipinti di Kyffin Williams",
   "orig": "'It's like you're in one of his paintings' Kyffin Williams' art brought to life",
   "lead": "Una mostra dedicata al pittore gallese Kyffin Williams utilizza una tecnologia immersiva simile a quella impiegata per le esposizioni su Van Gogh, Cézanne e LS Lowry, per far sembrare al visitatore di trovarsi dentro ai suoi quadri. L'iniziativa punta a far scoprire l'opera dell'artista a un pubblico più ampio attraverso proiezioni che animano i paesaggi e le scene ritratte da Williams, noto soprattutto per i suoi dipinti del paesaggio gallese. Lo riferisce BBC News.",
   "more": [
    "Le mostre immersive digitali, già usate per grandi nomi come Van Gogh, proiettano riproduzioni delle opere su grandi schermi o pareti, spesso accompagnate da musica, per offrire un'esperienza sensoriale diversa dalla visione tradizionale in galleria, rendendo l'arte più accessibile anche a chi non è abituato ai musei."
   ],
