   "id": "z46420800",
   "sez": "italia",
   "titolo": "Aggressione a un rabbino a Milano: la famiglia di uno dei giovani espulsi racconta il caso",
   "orig": "“Mio fratello ha chiesto scusa al rabbino. Ma non si può cacciare così un ragazzo nato in Italia”",
   "lead": "Dopo l'aggressione a un religioso ebraico a Milano, un giovane è stato espulso dall'Italia e un altro è stato trattenuto in un Centro per il rimpatrio (Cpr). Il fratello terzogenito della famiglia, di origine tunisina, racconta a la Repubblica che il parente coinvolto ha chiesto scusa al rabbino, ma contesta la decisione di espellere un ragazzo nato in Italia. Dice che la madre è distrutta e sottolinea che i figli studiano e lavorano, non conoscono l'arabo e sono rimasti delusi per non aver ottenuto la cittadinanza italiana.",
   "more": [
    "In Italia la cittadinanza per i figli di immigrati nati sul territorio non è automatica ma segue il principio dello ius soli temperato, che prevede requisiti come la residenza continuativa fino alla maggiore età: un tema oggetto di dibattito politico da anni, legato anche ai casi di giovani nati in Italia ma privi di cittadinanza."
   ],
