   "id": "z4785a674",
   "sez": "mondo",
   "titolo": "In Nuova Zelanda pazienti ricoverati non hanno potuto votare, denuncia il sindacato infermieri",
   "orig": "NZ Nurses Organisation claim Auckland hospital patients unable to vote",
   "lead": "L'organizzazione sindacale neozelandese NZ Nurses Organisation ha denunciato che almeno 12 pazienti ricoverati all'ospedale North Shore di Auckland non sono riusciti a votare nel giorno delle elezioni. Secondo il sindacato, questi pazienti sarebbero stati esclusi dal processo di voto per problemi organizzativi legati al loro stato di ricovero, un'esclusione che l'organizzazione considera rilevante per il diritto di voto dei cittadini ospedalizzati. Lo riferisce RNZ.",
   "more": [
    "In molti paesi con il voto in presenza sono previste procedure speciali, come urne mobili o voto per corrispondenza, per permettere a pazienti ricoverati o persone con mobilità limitata di esercitare il diritto di voto senza doversi spostare dal luogo di cura."
   ],
