   "id": "zdc5935ca",
   "sez": "ingegneria",
   "titolo": "Mecanoo trasforma l'ex caveau d'oro della banca centrale olandese nel \"salotto della città\" ad Amsterdam",
   "orig": "Mecanoo transforms former gold vault into \"city’s living room\" in renovation of De Nederlandsche Bank in Amsterdam",
   "lead": "Lo studio olandese Mecanoo ha completato una grande ristrutturazione della sede della De Nederlandsche Bank, la banca centrale dei Paesi Bassi ad Amsterdam, che ha previsto lo smantellamento di una torre di 14 piani e l'apertura al pubblico dell'ex caveau dell'oro dell'istituto. L'intervento punta a rendere più accessibili alcuni spazi dell'edificio, trasformandoli in un punto di incontro per la città. Lo riferisce Dezeen.",
   "more": [
    "Le banche centrali conservano tradizionalmente riserve d'oro in caveau fortemente protetti; la riconversione di questi spazi in aree pubbliche o culturali è una tendenza recente nell'architettura di riqualificazione di edifici istituzionali storici, che punta a renderli più aperti ai cittadini."
   ],
