   "id": "z2806d2d6",
   "sez": "mondo",
   "titolo": "In Estonia i primi soccorritori si esercitano in un'esercitazione contro attacchi con drone in una scuola",
   "orig": "Estonia's first responders hold school drone attack drills",
   "lead": "I servizi di emergenza estoni hanno condotto un'esercitazione realistica di grande scala in una scuola superiore dell'Estonia occidentale, per allenarsi a rispondere a un attacco con drone. L'iniziativa risponde alla crescente minaccia rappresentata dai velivoli senza pilota, un pericolo che le autorità estoni considerano in aumento anche in contesti civili come gli istituti scolastici. Lo riferisce ERR News.",
   "more": [
    "I paesi baltici, confinanti con la Russia, hanno intensificato negli ultimi anni le esercitazioni di difesa civile, incluse quelle contro attacchi con drone, in un contesto di crescente tensione geopolitica dopo l'invasione russa dell'Ucraina del 2022."
   ],
