   "id": "zb2341c01",
   "sez": "ambiente",
   "titolo": "Pesca intensiva e scienza carente: il commercio di squali azzurri tra Spagna e Taiwan",
   "orig": "OCEAN PLUNDER: Relentless fishing and dodgy science — Spain and Taiwan’s blue shark trade",
   "lead": "Un'inchiesta di Daily Maverick mostra come la pesca industriale abbia reso Spagna e Taiwan i maggiori paesi catturatori al mondo di squali azzurri. Secondo l'articolo, dati scientifici poco accurati e l'inazione politica stanno accelerando il sovrasfruttamento della specie, spingendo questi squali sempre più vicino al rischio di estinzione. L'inchiesta punta il dito su una combinazione di pesca intensiva e carenza di controlli adeguati nella gestione degli stock. Lo riferisce Daily Maverick.",
   "more": [
    "Gli squali azzurri sono tra le specie più pescate al mondo, spesso come catture accessorie o per il commercio delle pinne; la loro riproduzione lenta li rende particolarmente vulnerabili alla pesca eccessiva, mentre la mancanza di dati scientifici affidabili complica la definizione di quote di pesca sostenibili a livello internazionale."
   ],
