   "id": "z11b6a39b",
   "sez": "spazio",
   "titolo": "La sonda Voyager 1 sta per raggiungere un giorno luce dalla Terra",
   "orig": "NASA's Voyager 1 closes in on a light-day in interstellar space for a new distance record",
   "lead": "La sonda Voyager 1 della NASA sta per diventare il primo oggetto costruito dall'uomo a raggiungere la distanza di un giorno luce dalla Terra, mentre prosegue il suo viaggio nello spazio interstellare. Il traguardo, atteso mercoledì 18 novembre alle 7:16 ora di Brasilia, rappresenta un nuovo record di distanza per la missione spaziale più longeva della storia dell'umanità, lanciata decenni fa e ancora operativa nonostante complicazioni tecniche affrontate negli anni dagli ingegneri della missione.",
   "more": [
    "La Voyager 1, lanciata dalla NASA nel 1977, è l'oggetto costruito dall'uomo più distante dalla Terra. Un giorno luce corrisponde alla distanza percorsa dalla luce in 24 ore, circa 26 miliardi di chilometri. La sonda ha già superato i confini del sistema solare, entrando nello spazio interstellare nel 2012."
   ],
