   "sez": "prima",
   "titolo": "Il Papa dalle Ande: 'Mai cedere alla violenza'",
   "orig": "Il Papa dalle Ande: 'Mai cedere alla violenza, non è la via per il progresso'&nbsp;",
   "lead": "Papa Leone XIV, in visita in Perù, ha affermato dalle Ande che non si deve mai cedere alla violenza, definendola non la via per il progresso, esprimendo preoccupazione per le migrazioni forzate e per lo sfruttamento iniquo delle risorse del suolo. Il Pontefice è salito a oltre 3mila metri di altitudine a un mese dall'operazione al polmone subita, nell'ultima tappa del suo viaggio in America Latina, che prevede ancora incontri con fedeli e missionari a Cusco e Pucallpa. Lo riferisce ANSA.",
   "more": [
    "Leone XIV, succeduto a Papa Francesco, ha subito un intervento chirurgico al polmone circa un mese prima di questo viaggio. Il Perù, dove si trova la città di Cusco nelle Ande, è tradizionalmente un Paese a forte presenza cattolica e meta frequente di visite papali in America Latina."
   ],
