   "id": "z68ee4012",
   "sez": "mondo",
   "titolo": "Gli elettori di metà mandato ridisegnano gli equilibri nelle assemblee statali Usa",
   "orig": "Midterm voters ended the long-running GOP dominance in state legislatures",
   "lead": "Gli elettori delle elezioni di metà mandato negli Stati Uniti hanno posto fine al lungo predominio repubblicano in diverse assemblee legislative statali: in alcuni Stati i democratici hanno conquistato il controllo di assemblee prima divise, in altri hanno ridotto il predominio repubblicano. Tra i temi in agenda nelle nuove assemblee figurano il maggiore accesso alle cure sanitarie e nuovi limiti ai voucher scolastici. A una settimana dal voto, i democratici discutono come trasformare il nuovo sostegno tra i giovani uomini in un consenso duraturo, mentre i repubblicani cercano di capire perché il gruppo li abbia abbandonati. Lo riferisce NPR.",
   "more": [
    "Negli Stati Uniti le elezioni di metà mandato rinnovano anche numerose assemblee legislative statali, che determinano politiche su sanità, istruzione e voto. Il controllo di queste assemblee è spesso decisivo per l'approvazione di leggi locali e per gli equilibri politici in vista delle presidenziali."
   ],
