   "sez": "mondo",
   "titolo": "I Democratici socialisti di New York chiedono a Ocasio-Cortez di candidarsi alla presidenza",
   "orig": "New York Democratic Socialists urge Ocasio-Cortez to run for US president",
   "lead": "I delegati della convention del capitolo newyorkese dei Democratici Socialisti d'America hanno approvato una risoluzione che chiede formalmente alla deputata Alexandria Ocasio-Cortez di candidarsi alla presidenza degli Stati Uniti nel 2028. La risoluzione, approvata sabato, non costituisce un endorsement ufficiale da parte del Partito Democratico. Lo riferisce Al Jazeera.",
   "more": [
    "Alexandria Ocasio-Cortez è una delle figure più note dell'ala progressista del Partito Democratico statunitense, eletta alla Camera dei Rappresentanti per New York. I Democratici Socialisti d'America (DSA) sono un'organizzazione politica di sinistra che ha sostenuto diversi candidati progressisti negli ultimi anni."
   ],
