   "id": "zf6686282",
   "sez": "mondo",
   "titolo": "Costa Rica, le carceri ospitano quasi 8mila detenuti oltre la capacità",
   "orig": "Hacinamiento en cárceles de Costa Rica: casi 8.000 reclusos superan la capacidad disponible",
   "lead": "Le carceri della Costa Rica ospitano 21.153 detenuti, nonostante una capacità disponibile di sole 13.289 persone, con quasi 8mila reclusi oltre il limite previsto. Il ministero della Giustizia del Paese ha avvertito sul problema del sovraffollamento carcerario e sulla necessità di creare nuovi spazi detentivi per far fronte alla crescente popolazione reclusa. Lo riferisce La Nación CR.",
   "more": [
    "Il sovraffollamento carcerario è un problema comune a molti Paesi dell'America Centrale, spesso legato all'aumento dei tassi di criminalità e detenzione preventiva, con conseguenze sulle condizioni di vita dei detenuti e sulla gestione delle strutture penitenziarie."
   ],
