   "sez": "italia",
   "titolo": "Maltempo: allerta in 12 regioni italiane",
   "orig": "Maltempo, è ancora allerta in 12 Regioni",
   "lead": "L'Italia è colpita da una nuova ondata di maltempo il 15 novembre. Allerta meteo attiva in dodici regioni con piogge abbondanti, temporali diffusi e forti venti. I danni più rilevanti sono stati registrati in Campania, dove una frana ha interrotto la Costiera Amalfitana.",
   "more": [
    "Il maltempo concentra i suoi effetti sulle regioni centro-meridionali italiane, con particolare intensità in Campania dove la frana ha causato danni significativi alle infrastrutture viarie."
   ],
