     "t": "Racconta il ritrovamento di un ordigno vicino all'impianto BioUrja a Peoria, l'evacuazione entro 1 miglio e la definizione di \"minaccia credibile\" data dal capo della polizia. Cita FBI e sindaca di Peoria, nessun arresto né ferito.",
