     "t": "L'articolo non riguarda la notizia dell'ordigno in Illinois: tratta il ritrovamento di una tavoletta d'argilla di 4.300 anni vicino a Kirkuk, conservata a Harvard. Il giudizio su questa testata è quindi non pertinente al fatto in esame.",
