     "c": "Suva",
     "p": "XX",
     "t": "Riporta che l'ordine di evacuazione è stato revocato sabato dopo la perquisizione del sito da parte di FBI e ATF, senza trovare nulla \"di interesse\". Specifica le dimensioni dell'impianto (44,5 campi da football) e cita il capo della polizia Dixon, che evita il termine \"bomba\".",
