     "c": "Roseau",
     "p": "XX",
     "t": "Anche questo articolo non tratta la notizia dell'ordigno in Illinois, ma il salvataggio di tre uomini dispersi vicino alle Isole Aves, tratti in salvo dall'equipaggio della nave CMA CGM Marseille. Il giudizio su questa testata è quindi non pertinente al fatto in esame.",
     "b": "a"
